import re, sys, functools

def cut_modulo(x):
	y = x % 32768
	if y < 0:
		y += 32768
	return y

class berland_cpp_int:

	def __init__(self, x):
		self.value = cut_modulo(int(x))

	def __add__(self, x):
		return berland_cpp_int(cut_modulo(self.value + x.value))

	def __sub__(self, x):
		return berland_cpp_int(cut_modulo(self.value - x.value))

	def __mul__(self, x):
		return berland_cpp_int(cut_modulo(self.value * x.value))

	def __div__(self, x):
		return berland_cpp_int(cut_modulo(self.value // x.value))

	def __truediv__(self, x):
		return berland_cpp_int(cut_modulo(self.value // x.value))

	def __and__(self, x):
		return berland_cpp_int(cut_modulo(self.value & x.value))

	def __eq__(self, x):
		return self.value == x.value

	def __lt__(self, x):
		return self.value < x.value

	def __gt__(self, x):
		return self.value > x.value

	def __str__(self):
		return str(self.value)

	def __int__(self):
		return self.value

	def __hash__(self):
		return self.value

def translate_program(source_code):
	s = source_code
	s = s.replace('\n', '')
	s = s.replace('{', '')
	s = s.replace('}', '')
	s = re.sub('([0-9]+)', 'berland_cpp_int(\\1)', s)
	s = s.replace('int f(int n)', '\n@functools.lru_cache(maxsize=None)\ndef f(n):\n\t')
	s = re.sub('return(.*?);', 'return berland_cpp_int(\\1);', s)
	s = s.replace(';', '\n\t')
	s = s.replace('return', ':return')
	s = re.sub('\t[ :]+', '\t', s)
	return s
